const SNOW_RATIO = [0, 0.15, 0.30, 0.50];   // 난이도별 눈덩이 비율 (쉬움·보통·어려움=1:1)
const RESP_K = [1.5, 2, 2.6, 3.4, 4.5, 6, 8, 10, 13, 45];   // 움직임 반응 1~10
/* ============================== */
const W = 960, H = 600, GY = 548, SPR = 0.74, VMAX = 640, RIM = 104, BWH = 54;
const WALK = ['09', '10', '11', '10'];
const BK = { '01': [125, 238, 82, 22], '02': [130, 226, 80, 20], '03': [122, 230, 78, 20], '07': [125, 240, 82, 22], '09': [124, 226, 78, 20], '10': [176, 224, 76, 20], '11': [212, 228, 76, 20] };
