let noBanner = false, host = null, root = null, cvs = null, ctx = null, view = 1, raf = 0, snapC = null, built = false;
const R = (a, b) => a + Math.random() * (b - a), clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const sr = n => { const v = Math.sin(n * 127.1 + 311.7) * 43758.5453; return v - Math.floor(v); };
