  ctx = pc;
  c.save(); c.beginPath(); c.moveTo(cx - rx - 8, cy - ry); c.lineTo(cx - rx - 8, cy); c.ellipse(cx, cy - ry, rx + 2, ry + 3, 0, Math.PI, 0, true); c.lineTo(cx + rx + 8, cy - ry); c.lineTo(cx + rx + 40, f.h - f.ay + 4); c.lineTo(cx - rx - 40, f.h - f.ay + 4); c.closePath(); c.clip();
